package dev.oreslang.compiler;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Closed-world region/event-IR verifier for the future Oreslang hard-RT checker.
 *
 * <p>This verifies ONLY explicit, trusted IR facts passed by a compiler adapter.
 * It does not inspect source AST, JVM pointers, generated bytecode or hardware.
 * A report from caller-constructed events is never proof of actual actor safety.
 * Missing facts and unsupported effects fail closed rather than becoming zero.
 */
public final class RealtimeRegionFlow {
    private RealtimeRegionFlow() { }

    public enum Kind {
        ACTOR_LOCAL, SCOPED, SHARED_IMMUTABLE, MANAGED_HEAP, EXTERNAL_UNKNOWN
    }

    public enum Assurance { PROVEN, CONTRACTED, MEASURED, UNKNOWN }

    public record Region(
            String id, Kind kind, String actor, String parent,
            String shareDomain, long generation, long capacityBytes) {
        public Region {
            id = nonblank(id, "region ID");
            Objects.requireNonNull(kind, "region kind");
            if (generation < 0 || capacityBytes < 0) throw deny("invalid region generation/capacity");
            switch (kind) {
                case ACTOR_LOCAL -> {
                    nonblank(actor, "actor owner");
                    requireAbsent(parent, "actor-local parent");
                    requireAbsent(shareDomain, "actor-local share domain");
                }
                case SCOPED -> {
                    nonblank(actor, "scoped actor owner");
                    nonblank(parent, "scoped parent");
                    requireAbsent(shareDomain, "scoped share domain");
                }
                case SHARED_IMMUTABLE -> {
                    nonblank(shareDomain, "shared trust domain");
                    requireAbsent(parent, "shared region parent");
                    requireAbsent(actor, "shared region actor owner");
                }
                case MANAGED_HEAP, EXTERNAL_UNKNOWN -> {
                    requireAbsent(actor, "unqualified region actor owner");
                    requireAbsent(parent, "unqualified region parent");
                    requireAbsent(shareDomain, "unqualified share domain");
                }
            }
        }
    }

    public record Value(
            String id, String regionId, long bytes, boolean deeplyImmutable, boolean primitive) {
        public Value {
            id = nonblank(id, "value ID");
            regionId = nonblank(regionId, "value region ID");
            if (bytes < 1) throw deny("value allocation size must be finite and positive");
        }
    }

    public sealed interface Step permits
            Allocate, StoreReference, Borrow, EndBorrow, Write,
            Suspend, ReleaseScope, CopyToActor, ShareToActor, Call { }

    public record Allocate(Value value) implements Step {
        public Allocate { Objects.requireNonNull(value, "value"); }
    }

    /** A holder's lifetime and domain may never exceed the referent's. */
    public record StoreReference(String holderId, String referentId) implements Step {
        public StoreReference {
            nonblank(holderId, "holder");
            nonblank(referentId, "referent");
        }
    }

    public record Borrow(String loanId, String valueId, boolean mutable) implements Step {
        public Borrow {
            nonblank(loanId, "loan");
            nonblank(valueId, "borrow target");
        }
    }

    public record EndBorrow(String loanId) implements Step {
        public EndBorrow { nonblank(loanId, "loan"); }
    }

    public record Write(String valueId) implements Step {
        public Write { nonblank(valueId, "write target"); }
    }

    public record Suspend() implements Step { }

    /** Explicit end of nested scoped lifetime; all subsequent uses must fail. */
    public record ReleaseScope(String regionId) implements Step {
        public ReleaseScope { nonblank(regionId, "released region"); }
    }

    /** Copy only a known fixed-size primitive; no raw object or region pointer transfer. */
    public record CopyToActor(String valueId, String destinationActor) implements Step {
        public CopyToActor {
            nonblank(valueId, "copied value");
            nonblank(destinationActor, "destination actor");
        }
    }

    /** The recipient must already hold an explicit shared-domain grant. */
    public record ShareToActor(
            String valueId, String senderActor, String destinationActor) implements Step {
        public ShareToActor {
            nonblank(valueId, "shared value");
            nonblank(senderActor, "sending actor");
            nonblank(destinationActor, "receiving actor");
        }
    }

    /**
     * All nonlocal effects must have independently established upper bounds
     * and an acceptable source of assurance. A zero cost does not make FFI,
     * heap access, blocking, suspension or dynamic loading safe.
     */
    public record Call(
            String target, Assurance assurance, long boundedCopyBytes,
            boolean managedHeapAccess, boolean blockingIo, boolean suspends,
            boolean ffi, boolean dynamicLoad, boolean mayThrow) implements Step {
        public Call {
            nonblank(target, "call target");
            Objects.requireNonNull(assurance, "call assurance");
            if (boundedCopyBytes < 0) throw deny("negative call copy bound");
        }
    }

    public record Budget(long maxAllocationBytes, long maxCopyBytes, int maxSteps) {
        public Budget {
            if (maxAllocationBytes < 0 || maxCopyBytes < 0 || maxSteps < 1) {
                throw deny("invalid real-time region budgets");
            }
        }
    }

    /** Snapshot of region definitions and explicit per-actor share-domain grants. */
    public record Plan(
            List<Region> regions, Map<String, Set<String>> actorShareDomains,
            List<Step> steps) {
        public Plan {
            regions = List.copyOf(Objects.requireNonNull(regions, "regions"));
            steps = List.copyOf(Objects.requireNonNull(steps, "steps"));
            Objects.requireNonNull(actorShareDomains, "actorShareDomains");
            Map<String, Set<String>> grants = new LinkedHashMap<>();
            for (var entry : actorShareDomains.entrySet()) {
                nonblank(entry.getKey(), "granted actor");
                Set<String> domains = Set.copyOf(Objects.requireNonNull(entry.getValue(), "grants"));
                for (String domain : domains) nonblank(domain, "granted domain");
                grants.put(entry.getKey(), domains);
            }
            actorShareDomains = Map.copyOf(grants);
        }
    }

    public record Report(long allocatedBytes, long copiedBytes, int checkedSteps,
                         int regionsChecked, String assurance) { }

    private record Loan(String valueId, boolean mutable) { }

    public static Report verify(Plan plan, Budget budget) {
        Objects.requireNonNull(plan, "plan");
        Objects.requireNonNull(budget, "budget");
        Map<String, Region> regions = indexAndValidateRegions(plan.regions());
        if (plan.steps().size() > budget.maxSteps()) throw deny("IR step limit exceeded");
        Map<String, Value> values = new HashMap<>();
        Map<String, Long> regionBytes = new HashMap<>();
        Map<String, Loan> loans = new HashMap<>();
        Set<String> released = new HashSet<>();
        long allocated = 0;
        long copied = 0;
        int checked = 0;

        for (Step step : plan.steps()) {
            checked++;
            if (step instanceof Allocate event) {
                Value value = event.value();
                Region region = requireLiveRegion(regions, released, value.regionId());
                if (region.kind() == Kind.MANAGED_HEAP || region.kind() == Kind.EXTERNAL_UNKNOWN) {
                    throw deny("allocation into unqualified heap or unknown region");
                }
                if (region.kind() == Kind.SHARED_IMMUTABLE && !value.deeplyImmutable()) {
                    throw deny("mutable value cannot be allocated into immutable shared domain");
                }
                if (values.putIfAbsent(value.id(), value) != null) throw deny("duplicate value ID");
                long used = add(regionBytes.getOrDefault(region.id(), 0L), value.bytes());
                if (used > region.capacityBytes()) throw deny("region capacity exceeded: " + region.id());
                regionBytes.put(region.id(), used);
                allocated = add(allocated, value.bytes());
                if (allocated > budget.maxAllocationBytes()) throw deny("total allocation budget exceeded");
            } else if (step instanceof StoreReference event) {
                Value holder = value(values, regions, released, event.holderId());
                Value referenced = value(values, regions, released, event.referentId());
                if (holder.primitive()) throw deny("primitive value cannot store a reference");
                Region dst = regions.get(holder.regionId());
                Region src = regions.get(referenced.regionId());
                if (!mayReference(src, dst, plan.actorShareDomains(), regions)) {
                    throw deny("reference lifetime or actor/trust-domain escape");
                }
            } else if (step instanceof Borrow event) {
                Value target = value(values, regions, released, event.valueId());
                if (loans.containsKey(event.loanId())) throw deny("duplicate live loan ID");
                if (event.mutable() && target.deeplyImmutable()) throw deny("mutable borrow of frozen value");
                for (Loan loan : loans.values()) {
                    if (loan.valueId().equals(event.valueId()) && (loan.mutable() || event.mutable())) {
                        throw deny("conflicting mutable/shared loans");
                    }
                }
                loans.put(event.loanId(), new Loan(event.valueId(), event.mutable()));
            } else if (step instanceof EndBorrow event) {
                if (loans.remove(event.loanId()) == null) throw deny("ending nonexistent loan");
            } else if (step instanceof Write event) {
                Value v = value(values, regions, released, event.valueId());
                if (v.deeplyImmutable()) throw deny("mutation of immutable value");
                for (Loan loan : loans.values()) {
                    if (loan.valueId().equals(v.id())) throw deny("write while loan active");
                }
            } else if (step instanceof Suspend) {
                if (!loans.isEmpty()) throw deny("borrow across suspension lacks lifetime proof");
            } else if (step instanceof ReleaseScope event) {
                Region region = requireLiveRegion(regions, released, event.regionId());
                if (region.kind() != Kind.SCOPED) throw deny("only scoped regions may be released here");
                for (Region other : regions.values()) {
                    if (!released.contains(other.id()) && isAncestor(region.id(), other.id(), regions)
                            && !region.id().equals(other.id())) {
                        throw deny("cannot release scoped parent before nested children");
                    }
                }
                for (Loan loan : loans.values()) {
                    Value v = values.get(loan.valueId());
                    if (v != null && (v.regionId().equals(region.id())
                            || isAncestor(region.id(), v.regionId(), regions))) {
                        throw deny("cannot release region with live loan");
                    }
                }
                released.add(region.id());
            } else if (step instanceof CopyToActor event) {
                Value v = value(values, regions, released, event.valueId());
                Region source = regions.get(v.regionId());
                if (!v.primitive() || source.kind() == Kind.MANAGED_HEAP
                        || source.kind() == Kind.EXTERNAL_UNKNOWN) {
                    throw deny("cross-actor copy requires a known primitive value");
                }
                if (source.actor() == null || source.actor().equals(event.destinationActor())) {
                    throw deny("copy sender must be a distinct owning actor");
                }
                copied = add(copied, v.bytes());
                if (copied > budget.maxCopyBytes()) throw deny("copy budget exceeded");
            } else if (step instanceof ShareToActor event) {
                Value v = value(values, regions, released, event.valueId());
                Region source = regions.get(v.regionId());
                if (source.kind() != Kind.SHARED_IMMUTABLE || !v.deeplyImmutable()) {
                    throw deny("actor-private or mutable value cannot be shared by reference");
                }
                if (!hasGrant(plan.actorShareDomains(), event.senderActor(), source.shareDomain())
                        || !hasGrant(plan.actorShareDomains(), event.destinationActor(), source.shareDomain())) {
                    throw deny("missing explicit shared-domain grant");
                }
            } else if (step instanceof Call call) {
                if (call.assurance() != Assurance.PROVEN && call.assurance() != Assurance.CONTRACTED) {
                    throw deny("measured or unknown effects cannot qualify a hard-RT call");
                }
                if (call.managedHeapAccess() || call.blockingIo() || call.suspends()
                        || call.ffi() || call.dynamicLoad() || call.mayThrow()) {
                    throw deny("critical call contains unsupported or unsafe effect: " + call.target());
                }
                copied = add(copied, call.boundedCopyBytes());
                if (copied > budget.maxCopyBytes()) throw deny("call copy bound exceeded");
            } else {
                throw deny("unknown IR event type");
            }
        }
        if (!loans.isEmpty()) throw deny("borrow lifetime remains open at end of critical graph");
        return new Report(allocated, copied, checked, regions.size(),
                "EXPLICIT_REGION_EVENT_IR_ONLY;NOT_SOURCE_OR_VM_PROOF");
    }

    private static Map<String, Region> indexAndValidateRegions(List<Region> input) {
        Map<String, Region> regions = new LinkedHashMap<>();
        for (Region r : input) {
            if (regions.putIfAbsent(r.id(), r) != null) throw deny("duplicate region ID");
        }
        if (regions.size() > 1024) throw deny("too many region definitions");
        for (Region r : regions.values()) {
            if (r.kind() != Kind.SCOPED) continue;
            Region parent = regions.get(r.parent());
            if (parent == null || (parent.kind() != Kind.SCOPED && parent.kind() != Kind.ACTOR_LOCAL)
                    || !Objects.equals(parent.actor(), r.actor())) {
                throw deny("scoped region requires parent in the same actor");
            }
            Set<String> visited = new HashSet<>();
            Region cursor = r;
            while (cursor.parent() != null) {
                if (!visited.add(cursor.id())) throw deny("cyclic scoped lifetime ancestry");
                cursor = regions.get(cursor.parent());
                if (cursor == null) throw deny("missing scoped ancestor");
            }
        }
        return regions;
    }

    private static boolean mayReference(
            Region referent, Region holder, Map<String, Set<String>> grants,
            Map<String, Region> regions) {
        if (holder.kind() == Kind.MANAGED_HEAP || holder.kind() == Kind.EXTERNAL_UNKNOWN) return false;
        if (referent.kind() == Kind.MANAGED_HEAP || referent.kind() == Kind.EXTERNAL_UNKNOWN) return false;
        if (referent.kind() == Kind.SHARED_IMMUTABLE) {
            return holder.kind() != Kind.SHARED_IMMUTABLE
                    ? hasGrant(grants, holder.actor(), referent.shareDomain())
                    : Objects.equals(holder.shareDomain(), referent.shareDomain());
        }
        if (holder.kind() == Kind.SHARED_IMMUTABLE) return false;
        if (!Objects.equals(referent.actor(), holder.actor())) return false;
        return isAncestor(referent.id(), holder.id(), regions);
    }

    private static boolean isAncestor(String ancestor, String descendant, Map<String, Region> regions) {
        Region cursor = regions.get(descendant);
        int hops = 0;
        while (cursor != null && hops++ <= regions.size()) {
            if (cursor.id().equals(ancestor)) return true;
            cursor = cursor.parent() == null ? null : regions.get(cursor.parent());
        }
        return false;
    }

    private static Region requireLiveRegion(
            Map<String, Region> regions, Set<String> released, String id) {
        Region region = regions.get(id);
        if (region == null || released.contains(id)) throw deny("unknown or released region: " + id);
        for (String parent = region.parent(); parent != null; ) {
            if (released.contains(parent)) throw deny("released ancestor region");
            Region r = regions.get(parent);
            if (r == null) throw deny("missing region parent");
            parent = r.parent();
        }
        return region;
    }

    private static Value value(
            Map<String, Value> values, Map<String, Region> regions,
            Set<String> released, String id) {
        Value v = values.get(id);
        if (v == null) throw deny("unknown value: " + id);
        requireLiveRegion(regions, released, v.regionId());
        return v;
    }

    private static boolean hasGrant(Map<String, Set<String>> grants, String actor, String domain) {
        return actor != null && domain != null && grants.getOrDefault(actor, Set.of()).contains(domain);
    }

    private static long add(long a, long b) {
        try { return Math.addExact(a, b); }
        catch (ArithmeticException overflow) { throw deny("region resource bound overflow"); }
    }

    private static String nonblank(String id, String label) {
        if (id == null || id.isBlank()) throw deny("missing " + label);
        return id;
    }

    private static void requireAbsent(String value, String label) {
        if (value != null) throw deny("unexpected " + label);
    }

    private static IllegalArgumentException deny(String reason) {
        return new IllegalArgumentException("RT-REGION: " + reason);
    }
}
